"use strict";(self.webpackChunkkiwi_wiki=self.webpackChunkkiwi_wiki||[]).push([["44683"],{7222(n){n.exports=JSON.parse('{"tag":{"label":"Linux","permalink":"/en/docs/tags/linux","allTagsPath":"/en/docs/tags","count":55,"items":[{"id":"HomeLab/Network/Proxy/w-0076","title":"3X-UI + Traefik v3 Three Independent Domains Single 443 Port Multiplexing Deployment","description":"Multiplexing 3X-UI panel, VLESS-Reality TCP passthrough, and VLESS-WS+CDN nodes over a single 443 port using Traefik v3 across independent domains.","permalink":"/en/docs/HomeLab/Network/Proxy/w-0076"},{"id":"HomeLab/Linux/Tips/w-0021","title":"Alpine Linux / apk Practical Commands and Docker Optimization Notes","description":"Practical notes on Alpine Linux package management tool apk for routine maintenance, Dockerfile image slimming parameters, and repository configuration tips.","permalink":"/en/docs/HomeLab/Linux/Tips/w-0021"},{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0028","title":"Arch Linux All-in-One Automated Install Script: Nextcloud Deployment (nextc_arch.sh)","description":"A record of an early shell script that automatically deployed Nextcloud, MariaDB, PHP-FPM, and Nginx inside an Arch Linux chroot (superseded by archinstall and Docker).","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0028"},{"id":"HomeLab/Linux/ArchLinux/w-0005","title":"Arch Linux Automated Installation Guide","description":"Introduces how to use the official interactive Arch Linux installer archinstall to configure disk partitioning, kernels, and desktop environments, and export JSON configuration files for repeatable deployments.","permalink":"/en/docs/HomeLab/Linux/ArchLinux/w-0005"},{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0025","title":"Arch Linux Install Script: Architecture Overview","description":"Documents the architecture design and staged arch-chroot execution flow of an early custom all-in-one Arch Linux installation script (now superseded by archinstall).","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0025"},{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0027","title":"Arch Linux Install Script: Basic Edition","description":"Documents the architecture and step-by-step breakdown of an early custom minimal Arch Linux automated installation script (simple_arch.sh), now superseded by archinstall and archived.","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0027"},{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0026","title":"Arch Linux Install Script: Basic Installation","description":"Documents the disk partitioning, package installation, and chroot workflow of an early custom Arch Linux automated installation script (arch.sh), now superseded by the official archinstall tool.","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0026"},{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0030","title":"Arch Linux Install Script: Gateway + V2Ray Edition","description":"Documents the section-by-section breakdown and complete source code of the legacy Arch Linux dual-NIC gateway installation script arch_v2ray_gate.sh (now superseded by archinstall).","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0030"},{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0029","title":"Arch Linux Install Script: V2Ray Edition","description":"Analysis of an archived Arch Linux chroot automated installation script covering timezone, netctl networking, user setup, V2Ray, and GRUB configuration.","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0029"},{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0031","title":"Arch Linux Installation Script: Gateway+ V2Ray ver.K","description":"Documents the legacy Arch Linux dual-NIC gateway installation script arch_v2ray_gate_k.sh with section-by-section explanations and full source code (unmaintained and superseded by archinstall).","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0031"},{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0024","title":"Arch Linux Installation Script: Preface and Scope","description":"Documents the target environment and usage of a custom Arch Linux automated installation script, now archived after being superseded by the official archinstall.","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0024"},{"id":"HomeLab/Linux/ArchLinux/w-0002","title":"Arch-Based Pacman / Yay Practical Commands and Maintenance Tips","description":"A compilation of commonly used pacman and yay package installation, orphan cleanup, cache maintenance, and downgrade tips for Arch Linux and Manjaro.","permalink":"/en/docs/HomeLab/Linux/ArchLinux/w-0002"},{"id":"HomeLab/Automation/ShellScript/w-0084","title":"Bash / Shell Terminal Colors and Text Formatting","description":"A guide to Bash and Shell terminal ANSI/SGR color codes, text style controls, 256-color and RGB true color modes, and logging helper function patterns.","permalink":"/en/docs/HomeLab/Automation/ShellScript/w-0084"},{"id":"HomeLab/Automation/ShellScript/w-0087","title":"Bash Interactive Arrow Key Menu (TUI Menu)","description":"Introduce a Bash interactive arrow key menu function using relative cursor positioning, supporting dynamic directory arrays and Ctrl+C interrupt restoration.","permalink":"/en/docs/HomeLab/Automation/ShellScript/w-0087"},{"id":"HomeLab/Automation/ShellScript/w-0086","title":"Bash Loop Flow Control, Case Conditional Branching, and Interactive Menus","description":"A guide on Bash loop control keywords (break, continue, exit), practical usages of while/for loops, and interactive menu templates using case and select.","permalink":"/en/docs/HomeLab/Automation/ShellScript/w-0086"},{"id":"HomeLab/Automation/ShellScript/w-0085","title":"Bash Shell Variable Management, Special Automatic Variables, and Empty Variables","description":"Introduction to Bash Shell variable assignment, scopes, special automatic variables, built-in environment variables, parameter expansion defensive practices, and read command interactive input practices.","permalink":"/en/docs/HomeLab/Automation/ShellScript/w-0085"},{"id":"HomeLab/Tools/Shell/w-0094","title":"Cross-Platform Setup for Zsh and Powerlevel10k Terminal Customization","description":"Complete steps for installing Zsh, Powerlevel10k, Manjaro Zsh configurations, and Nerd Fonts across Arch Linux, FreeBSD, and WSL environments.","permalink":"/en/docs/HomeLab/Tools/Shell/w-0094"},{"id":"HomeLab/Linux/Debian/w-0012","title":"Debian / Ubuntu APT Package Management and System Maintenance","description":"A guide covering apt and nala package updates, removal and cleanup, downgrade pinning, and signed-by key configuration for Debian and Ubuntu systems.","permalink":"/en/docs/HomeLab/Linux/Debian/w-0012"},{"id":"HomeLab/Tools/Misc/w-0099","title":"Disk Space Analysis and Management Guide (du / ncdu / duf / gdu)","description":"Compares and introduces common disk space analysis tools on Linux and FreeBSD, including installation and practical commands for du, ncdu, duf, and gdu.","permalink":"/en/docs/HomeLab/Tools/Misc/w-0099"},{"id":"Games/EmuDeck/w-0117","title":"EmuDeck Installation and Cross-Platform Configuration (Windows / Linux)","description":"Explains how to deploy EmuDeck on Windows and Linux, combining NAS read-only shared ROMs/BIOS, multi-account save isolation, and troubleshooting the adb.zip freeze issue.","permalink":"/en/docs/Games/EmuDeck/w-0117"},{"id":"HomeLab/Linux/WSL/w-0019","title":"Enabling QEMU/KVM Nested Virtualization and Virt-Manager in WSL2","description":"Instructions on how to enable nested virtualization in Windows WSL2, and set up QEMU/KVM, Virt-Manager, and VirtioFS shared folders in an Arch Linux environment.","permalink":"/en/docs/HomeLab/Linux/WSL/w-0019"},{"id":"HomeLab/Linux/Independent/w-0015","title":"Gentoo / Portage & Emerge Practical Commands and Maintenance","description":"Organizes Gentoo Linux Portage and emerge package management commands, covering system updates, orphan cleanup, package masking, and compilation acceleration tips.","permalink":"/en/docs/HomeLab/Linux/Independent/w-0015"},{"id":"HomeLab/Tools/Misc/w-0102","title":"Homebrew on Linux (Linuxbrew) Practical Notes","description":"Guides installing and using Homebrew on Linux environments without root privileges, covering daily package management, cache cleanup, glibc dependency solutions, and Brewfile restoration.","permalink":"/en/docs/HomeLab/Tools/Misc/w-0102"},{"id":"HomeLab/Linux/Tips/w-0023","title":"KDE Plasma Post-Login Freezes, Black Screen Delays, and Session Corruption","description":"Explains the causes of post-login black screen delays and forced restoration of old windows in KDE Plasma 5 and 6, and provides reset and troubleshooting steps to clear corrupted sessions and cache files.","permalink":"/en/docs/HomeLab/Linux/Tips/w-0023"},{"id":"HomeLab/Automation/ShellScript/w-0083","title":"Linux / Bash Shell Special Characters and Wildcards","description":"A comprehensive guide and quick reference for common special control characters, wildcards (globbing), logical operators, and brace expansions in Linux and Bash Shell.","permalink":"/en/docs/HomeLab/Automation/ShellScript/w-0083"},{"id":"HomeLab/Tools/Shell/w-0096","title":"Linux and FreeBSD Chinese/Japanese Input Method Setup Guide (Fcitx5)","description":"Learn how to install CJK fonts and the Fcitx5 Chinese/Japanese input method on Arch Linux, Debian/Ubuntu, Fedora, and FreeBSD, and configure Wayland and X11 environment variables.","permalink":"/en/docs/HomeLab/Tools/Shell/w-0096"},{"id":"HomeLab/Automation/ShellScript/w-0088","title":"Linux Command Line Text to Table Formatting (CLI Table Formatting)","description":"Techniques for rapidly formatting delimited text into tables in the Linux terminal using column, sed, awk, and modern CLI tools.","permalink":"/en/docs/HomeLab/Automation/ShellScript/w-0088"},{"id":"HomeLab/Tools/Misc/w-0101","title":"Linux Cross-Distribution Package Format Guide: Flatpak, Snap, and AppImage","description":"Compare the sandboxing mechanisms, use cases, and common command operations of the three major cross-distribution Linux package formats: Flatpak, Snap, and AppImage.","permalink":"/en/docs/HomeLab/Tools/Misc/w-0101"},{"id":"HomeLab/Linux/Tips/w-0022","title":"Linux System Password Expiry and Complexity Management","description":"Introduces how to manage account password expiration using the chage command in Linux, and set password complexity policies using /etc/security/pwquality.conf.","permalink":"/en/docs/HomeLab/Linux/Tips/w-0022"},{"id":"HomeLab/Linux/Archive/Manjaro/w-0032","title":"Manjaro KDE 21.0.7 System Tweaks and Common Applications List","description":"Documents past system tweaks, VM display fixes, and common application installation lists when using Manjaro KDE 21.0.7 as a desktop environment (archived).","permalink":"/en/docs/HomeLab/Linux/Archive/Manjaro/w-0032"},{"id":"HomeLab/Linux/Archive/Manjaro/w-0036","title":"Manjaro KDE Environment Automated Installation Script","description":"Documents an early automated installation script plan for quickly deploying a personal Manjaro KDE desktop environment and common software (unmaintained).","permalink":"/en/docs/HomeLab/Linux/Archive/Manjaro/w-0036"},{"id":"HomeLab/Linux/Archive/Manjaro/w-0035","title":"Manjaro KDE xrdp Remote Desktop Host Setup Guide","description":"Records the steps for installing and configuring an xrdp remote desktop host on early Manjaro (KDE Plasma 5), along with ~/.xinitrc adjustment notes.","permalink":"/en/docs/HomeLab/Linux/Archive/Manjaro/w-0035"},{"id":"HomeLab/Linux/ArchLinux/w-0007","title":"Manjaro Linux Desktop Features and Insights on Migrating to Arch Linux","description":"A retrospective and review of starting out with Manjaro as an introduction to Linux desktops, and eventually migrating to vanilla Arch Linux in pursuit of a clean system.","permalink":"/en/docs/HomeLab/Linux/ArchLinux/w-0007"},{"id":"HomeLab/Linux/Archive/Manjaro/w-0033","title":"Manjaro Linux Mirrorlist Configuration and Speed Testing","description":"Historical command notes on updating the mirror list by country or connection speed using pacman-mirrors in early Manjaro Linux setups.","permalink":"/en/docs/HomeLab/Linux/Archive/Manjaro/w-0033"},{"id":"HomeLab/Linux/Archive/WSL/w-0039","title":"ManjaroWSL (WSL2) Installation and Desktop Environment Setup","description":"Historical archive notes on manually installing ManjaroWSL on legacy Windows WSL2, configuring Zsh / Xfce4 desktop environment, and setting up genie systemd.","permalink":"/en/docs/HomeLab/Linux/Archive/WSL/w-0039"},{"id":"HomeLab/Linux/Archive/WSL/w-0040","title":"ManjaroWSL2 (based on wsldl) Installation and Chinese IME Setup Notes","description":"Notes on installing Manjaro in Windows WSL environment via the wsldl project ManjaroWSL2, configuring fcitx Chinese input method, and testing I/O performance.","permalink":"/en/docs/HomeLab/Linux/Archive/WSL/w-0040"},{"id":"HomeLab/Tools/Editor/Vi/w-0093","title":"Neovim and NvChad Installation, Configuration, and Keybinding Reference","description":"Introduces basic Neovim installation, NvChad configuration structure, common keybindings, and managing LSPs and formatters with Mason.","permalink":"/en/docs/HomeLab/Tools/Editor/Vi/w-0093"},{"id":"HomeLab/Linux/Independent/w-0016","title":"NixOS / NIX-ENV Practical Commands and Maintenance","description":"Organizes daily commands for NixOS and Standalone Nix, covering the /nix/store concept, system updates, garbage collection, generation rollbacks, and nix-shell temporary environments.","permalink":"/en/docs/HomeLab/Linux/Independent/w-0016"},{"id":"HomeLab/Tools/Misc/w-0103","title":"Node.js Modern Package and Environment Management Practical Notes","description":"A guide on installing, maintaining, and applying CI/CD best practices for Node.js version managers (NVM, fnm) and package managers (npm, pnpm).","permalink":"/en/docs/HomeLab/Tools/Misc/w-0103"},{"id":"HomeLab/Linux/SUSE/w-0013","title":"openSUSE / SUSE / Zypper Practical Commands and Maintenance","description":"Compiles SUSE and openSUSE Zypper package management commands, covering Leap and Tumbleweed update differences, dependency cleanup, Snapper snapshot rollback, and package locking tips.","permalink":"/en/docs/HomeLab/Linux/SUSE/w-0013"},{"id":"HomeLab/Tools/Misc/w-0104","title":"Python / pip Modern Package and Virtual Environment Management Practical Notes","description":"Practical commands for Python virtual environments (venv), global CLI isolation tool pipx, pip cache cleanup, Docker optimization, and the ultra-fast alternative tool uv.","permalink":"/en/docs/HomeLab/Tools/Misc/w-0104"},{"id":"HomeLab/Linux/RedHat/w-0008","title":"Red Hat / Fedora DNF Practical Commands and Maintenance","description":"Compiles common commands, history rollbacks, version locking, and third-party repository configuration tips for DNF and TDNF package management across Red Hat, RHEL, Fedora, and Photon OS.","permalink":"/en/docs/HomeLab/Linux/RedHat/w-0008"},{"id":"HomeLab/Linux/Independent/w-0014","title":"Running GUI Applications as root in Linux Desktop Environments","description":"Methods for running GUI applications with root privileges in Linux desktop environments using su, sudo, kdesu, pkexec, and Polkit rules.","permalink":"/en/docs/HomeLab/Linux/Independent/w-0014"},{"id":"HomeLab/Tools/Misc/w-0100","title":"SNMP (Simple Network Management Protocol) and System Monitoring Tools","description":"Learn how the SNMP protocol works and its version differences, and get examples of deploying Net-SNMP (SNMPv3) and modern monitoring integrations on Linux and FreeBSD.","permalink":"/en/docs/HomeLab/Tools/Misc/w-0100"},{"id":"HomeLab/Linux/ArchLinux/w-0003","title":"systemd-boot Complete Guide and Pacman Hook Automation","description":"Introduces the architecture of systemd-boot and daily bootctl commands in a UEFI environment, and explains how to automatically sync the bootloader and verify kernel configurations via Pacman Hooks.","permalink":"/en/docs/HomeLab/Linux/ArchLinux/w-0003"},{"id":"HomeLab/Tools/Shell/w-0095","title":"Terminal Multiplexers and Session Management","description":"Compare terminal multiplexers like tmux, GNU screen, and zellij, and organize installation methods, common shortcuts, and WSL automatic takeover settings.","permalink":"/en/docs/HomeLab/Tools/Shell/w-0095"},{"id":"HomeLab/Linux/ArchLinux/w-0004","title":"The Role and Positioning of Arch Linux in HomeLab","description":"Explains the role and positioning of Arch Linux as a desktop environment (KDE Plasma 6) in a HomeLab, leveraging its KISS principle and AUR ecosystem.","permalink":"/en/docs/HomeLab/Linux/ArchLinux/w-0004"},{"id":"HomeLab/Linux/RedHat/w-0009","title":"The Role and Positioning of Oracle Linux in HomeLab and OCI","description":"Explains Oracle Linux 10 as the default instance for OCI Always Free tier, and its role in running Docker and WireGuard within HomeLab cloud nodes.","permalink":"/en/docs/HomeLab/Linux/RedHat/w-0009"},{"id":"HomeLab/Linux/RedHat/w-0010","title":"The Role and Positioning of VMware Photon OS in HomeLab","description":"Explains VMware Photon OS 5.0 as a lightweight container host for ESXi and its role in running Docker services in the HomeLab.","permalink":"/en/docs/HomeLab/Linux/RedHat/w-0010"},{"id":"HomeLab/Linux/WSL/w-0017","title":"The Role and Purpose of WSL in HomeLab","description":"Explanation of WSL\'s role and primary services (paired with Arch Linux) as a node and VPN springboard connecting back to the HomeLab in a corporate environment.","permalink":"/en/docs/HomeLab/Linux/WSL/w-0017"},{"id":"HomeLab/Linux/Archive/Manjaro/w-0034","title":"Troubleshooting Manjaro 21 Boot Black Screen and Display Issues in VMware VMs","description":"Documentation of historical troubleshooting for boot failures and missing virtual machine display drivers (video-virtualmachine) when installing Manjaro 21 KDE on VMware Workstation.","permalink":"/en/docs/HomeLab/Linux/Archive/Manjaro/w-0034"},{"id":"HomeLab/Network/Proxy/w-0075","title":"V2Ray / Xray Multi-Platform Client Recommendations and Settings","description":"A compilation of recommended proxy clients and setup tutorials supporting VLESS Reality and WS+TLS+CDN across Android, iOS, Windows, and Linux platforms.","permalink":"/en/docs/HomeLab/Network/Proxy/w-0075"},{"id":"HomeLab/Tools/Editor/Vi/w-0091","title":"Vi / Vim Editor General Commands and Advanced Tips","description":"Compiles common commands for the Vi / Vim editor in Normal and Command-line modes, covering save/quit, editing shortcuts, and search & global string replacement.","permalink":"/en/docs/HomeLab/Tools/Editor/Vi/w-0091"},{"id":"HomeLab/Linux/WSL/w-0018","title":"WSL (Store Version) Installation and ArchWSL Initialization Setup","description":"Covers installing the Store version of WSL on Windows 10/11, configuring Windows Terminal with Nerd Fonts, and setting up ArchWSL initialization and systemd.","permalink":"/en/docs/HomeLab/Linux/WSL/w-0018"},{"id":"HomeLab/Linux/WSL/w-0020","title":"WSL2 Custom Linux Kernel Compilation and Replacement","description":"Instructions on how to export config and compile a custom Linux Kernel (adding TC/QoS modules) under Arch Linux (WSL2), then load it via .wslconfig.","permalink":"/en/docs/HomeLab/Linux/WSL/w-0020"}],"unlisted":false}}')}}]);